135	// AddImageResults takes one registry's answer. It returns false, touching
136	// nothing, when the answer belongs to another lot. pendingSearches never goes
137	// below zero.
138	func (b *RegistryBrowser) AddImageResults(msg ImageSearchResultMsg) bool {
139		if msg.Gen != b.gen {
140			return false
141		}
142		if b.pendingSearches > 0 {
143			b.pendingSearches--
144		}
145		if msg.Err == nil {
146			for _, img := range msg.Images {
147				img.EntryKey = msg.EntryKey
148				b.images = append(b.images, img)
149			}
150		}
151		b.rebuildSearchTable()
152		return true
153	}
154	
155	// handleImagesKeyMsg handles the keys of the level 1 table. left goes straight
156	// back to the form; esc acts in order: the filter bar while it is open, then a
157	// confirmed query, then it cancels the lot and goes back to the form (which
158	// keeps the typed name and the selection). The lot's late answers are no
159	// longer wanted and are dropped
160	// (TestEscAtLevelOneCancelsTheLotAndIgnoresItsLateAnswers). enter does
161	// nothing: a row has no action yet; → opens the row's tags.
162	func (b *RegistryBrowser) handleImagesKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
163		if b.searchTable.InEditMode() {
164			return b, b.searchTable.Update(msg)
165		}
166		switch msg.String() {
167		case "right":
168			return b.openSelectedImageTags()
169		case "esc":
170			if bar := b.searchTable.FilterBar(); bar.SearchQuery() != "" {
171				bar.ClearSearch()
172				b.searchTable.SetItems(b.searchTable.Items())
173				return b, nil
174			}
175			return b.backToForm()
176		case "left":
177			return b.backToForm()
178		case "enter":
179			return b, nil
180		}
181		return b, b.searchTable.Update(msg)
182	}
183	
184	// backToForm cancels the lot and returns to the form, which keeps the typed
185	// name and the selection. Late answers of the lot are dropped.
186	func (b *RegistryBrowser) backToForm() (*RegistryBrowser, tea.Cmd) {
187		b.abandonLot()
188		b.state = browserStateInput
189		b.searchTable.Blur()
190		b.updateFocus()
191		return b, nil
192	}
193	
194	// handleImageSearchResult records one registry's answer; a stale one is ignored.
195	func (m Model) handleImageSearchResult(msg ImageSearchResultMsg) (tea.Model, tea.Cmd) {
196		if m.registryBrowser == nil || !m.registryBrowser.AddImageResults(msg) {
197			return m, nil
198		}
199		if msg.Err != nil {
200			alias := msg.EntryKey
201			if e := m.registryBrowser.entryFor(msg.EntryKey); e != nil {
202				alias = entryAlias(*e)
203			}
204			if errors.Is(msg.Err, imagesearch.ErrUnsupported) {
205				log.Printf("INFO [oci_resources] image search on %s: %s", alias, msg.Err)
206				return m, nil
207			}
208			log.Printf("ERROR [oci_resources] image search on %s: %s", alias, searchErrorCause(msg.Err))
209		}
210		return m, nil
211	}
212	
213	// searchErrorCause is the loggable text of a search error. A *url.Error holds
214	// the full request URL, which carries the text the user typed, so only its Op
215	// and Err are kept.
216	func searchErrorCause(err error) string {
217		var ue *url.Error
218		if errors.As(err, &ue) {
219			return jobs.SafeCause(errors.New(ue.Op + ": " + jobs.SafeCause(ue.Err)))
220		}
221		return jobs.SafeCause(err)
222	}
223	
224	// handleRegistryBrowserWarn shows the browser's warning in the footer.
225	func (m Model) handleRegistryBrowserWarn(msg RegistryBrowserWarnMsg) (tea.Model, tea.Cmd) {
226		return m, m.footer.Warn(strings.TrimSpace(msg.Text))
227	}
228	
229	// tagsLoadFailedText is the footer text of a failed tag listing opened by →.
230	const tagsLoadFailedText = "Could not load tags"
231	
232	// selectedImage returns the level 1 row under the cursor with its registry
233	// entry; false when there is no row or the entry is no longer known.
234	func (b *RegistryBrowser) selectedImage() (searchRow, *browserRegistryEntry, bool) {
235		row, ok := b.searchTable.Selected()
236		if !ok {
237			return searchRow{}, nil, false
238		}
239		entry := b.entryFor(row.img.EntryKey)
240		return row, entry, entry != nil
241	}
242	
243	// imageDrillIn reports whether → has an image to open: a row under the cursor
244	// whose registry entry is still known. One computation for the header and the
245	// handler (Rule 130).
246	func (b *RegistryBrowser) imageDrillIn() shortcut.Availability {
247		if _, _, ok := b.selectedImage(); !ok {
248			return shortcut.Unavailable(reasonNoImage)
249		}
250		return shortcut.Availability{}
251	}
252	
253	// openSelectedImageTags lists the tags of the selected level 1 row, on that
254	// row's registry only, with the row's final repository as is (no prefix, no
255	// library/ added again). Without a row it changes nothing and warns. A level 1
256	// search still running is cancelled: the browser has one lot at a time.
257	func (b *RegistryBrowser) openSelectedImageTags() (*RegistryBrowser, tea.Cmd) {
258		if av := b.imageDrillIn(); !av.Enabled() {
259			reason := av.Reason
260			return b, func() tea.Msg { return RegistryBrowserWarnMsg{Text: reason} }
261		}
262		row, entry, _ := b.selectedImage()
263		b, cmd := b.startTagRequests([]tagRequest{b.newTagRequest(*entry, row.img.Repo)}, true)
264		b.tagsImage = row.img.Name
265		return b, cmd
266	}
