	t.Helper()
	m = typeInto(t, m, text)
	return step(t, m, testutil.Key("enter"))
}

func uncheckAll(m Model) {
	for _, e := range m.registryBrowser.entries {
		m.registryBrowser.selectedRegs[e.key] = false
	}
}

